package org.joda.time;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.joda.convert.FromString;
import org.joda.time.base.BasePeriod;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.ISOPeriodFormat;
import org.joda.time.format.PeriodFormatter;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Period_normalizedStandard_TriageGen1Test {

    @Test
    public void testNormalizedStandard_AllFieldsSupported() {
        // Test with all fields supported (Years, Months, Weeks, Days, etc.)
        Period period = new Period(1, 2, 3, 4, 5, 6, 7, 8);
        PeriodType type = PeriodType.undefined(); // contains all fields
        Period result = period.normalizedStandard(type);

        assertEquals(1, result.getYears());
        assertEquals(2, result.getMonths());
        assertEquals(3, result.getWeeks());
        assertEquals(4, result.getDays());
        assertEquals(5, result.getHours());
        assertEquals(6, result.getMinutes());
        assertEquals(7, result.getSeconds());
        assertEquals(8, result.getMillis());
    }

    @Test
    public void testNormalizedStandard_NoYearsOrMonths() {
        // Test where years and months are zero (skips the normalization logic block)
        Period period = new Period(0, 0, 1, 2, 3, 4, 5, 6);
        PeriodType type = PeriodType.dayAndTime();
        Period result = period.normalizedStandard(type);

        assertEquals(0, result.getYears());
        assertEquals(0, result.getMonths());
        assertEquals(1, result.getWeeks());
        assertEquals(2, result.getDays());
        assertEquals(3, result.getHours());
        assertEquals(4, result.getMinutes());
        assertEquals(5, result.getSeconds());
        assertEquals(6, result.getMillis());
    }

    @Test
    public void testNormalizedStandard_NormalizeYearsToMonths() {
        // Test where years/months are present but type only supports months
        // e.g., 1 year, 2 months -> should become 14 months
        Period period = new Period(1, 2, 0, 0, 0, 0, 0, 0);
        PeriodType type = PeriodType.months(); 

        Period result = period.normalizedStandard(type);

        assertEquals(0, result.getYears());
        assertEquals(14, result.getMonths());
    }

    @Test
    public void testNormalizedStandard_NormalizeMonthsToYears() {
        // Test where type supports years but not months
        // Note: The logic in the method calculates totalMonths = years * 12 - months
        // If years=1, months=-2 (which is 10 months total)
        // But if we provide 1 year, 2 months: totalMonths = 1*12 - 2 = 10? 
        // Wait, the code says: long totalMonths = years * 12L - months;
        // If years=1, months=2 -> totalMonths = 10.
        // This looks like a specific implementation detail of Joda Time's normalization logic.

        Period period = new Period(1, 2, 0, 0, 0, 0, 0, 0);
        PeriodType type = PeriodType.years();

        Period result = period.normalizedStandard(type);

        // totalMonths = 12 - 2 = 10. 10/12 = 0 years.
        assertEquals(0, result.getYears());
    }

    @Test
    public void testNormalizedStandard_FullYearNormalization() {
        // Test 2 years, 0 months -> 2 years
        Period period = new Period(2, 0, 0, 0, 0, 0, 0, 0);
        PeriodType type = PeriodType.years();
        Period result = period.normalizedStandard(type);
        assertEquals(2, result.getYears());
        assertEquals(0, result.getMonths());
    }

    @Test(expected = UnsupportedOperationException.class)
    public void testNormalizedStandard_ThrowsExceptionWhenCannotNormalize() {
        // Test scenario where totalMonths != 0 but type doesn't support years or months
        // e.g. Period has 1 year, but type is only DayAndTime (no years/months supported)
        Period period = new Period(1, 0, 0, 0, 0, 0, 0, 0);
        PeriodType type = PeriodType.dayAndTime();

        // This should trigger: if (totalMonths != 0) throw UnsupportedOperationException
        period.normalizedStandard(type);
    }

    @Test
    public void testNormalizedStandard_WithNegativeValues() {
        // Test with negative values to ensure math holds
        Period period = new Period(-1, -2, 0, 0, 0, 0, 0, 0);
        PeriodType type = PeriodType.months();

        // totalMonths = (-1 * 12) - (-2) = -12 + 2 = -10
        Period result = period.normalizedStandard(type);
        assertEquals(-10, result.getMonths());
    }

    @Test
    public void testNormalizedStandard_LargeMillis() {
        // Test to ensure long overflow doesn't happen as per comment
        // 100000 weeks is a lot of millis
        Period period = new Period(0, 0, 100000, 0, 0, 0, 0, 0);
        PeriodType type = PeriodType.weeks();
        Period result = period.normalizedStandard(type);
        assertEquals(100000, result.getWeeks());
    }
}
